Æ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ25.</param>
    /// <param name="blocks">The skills to plan, weakest first. Empty means the plan has no steps.</param>
    public static IReadOnlyList<PlannedPathStep> Plan(
        decimal weeklyStudyHours,
        IReadOnlyList<SkillPlanBlock> blocks)
    {
        var weekBudget = (int)Math.Round(weeklyStudyHours * 60m);
        if (weekBudget <= 0 || blocks.Count == 0)
        {
            return [];
        }

        var stepsPerWeek = Math.Clamp((int)Math.Round(weekBudget / 40m), MinimumStepsPerWeek, MaximumStepsPerWeek);
        var planned = new List<PlannedPathStep>(WindowWeeks * MaximumStepsPerWeek);

        for (var week = 1; week <= WindowWeeks; week++)
        {
            // 15% mock, at the end of each two-week cycle, and only when a mock exists to sit.
            var wantsMock = week % 2 == 0 && blocks.Any(b => b.MockExamId is not null);

            // 25% lesson plus spaced review; a three-step week is already spent on practice.
            var wantsLesson = stepsPerWeek > MinimumStepsPerWeek && blocks.Any(b => b.LessonId is not null);

            var drillCount = stepsPerWeek - (wantsLesson ? 1 : 0) - (wantsMock ? 1 : 0);
            if (drillCount < 0)
            {
                drillCount = 0;
            }

            var kinds = BuildWeekKinds(blocks, week, drillCount, wantsLesson, wantsMock);
            if (kinds.Count == 0)
            {
                continue;
            }

            // The week's minutes add up to the goal's pace, shared evenly. The remainder is the
            // learner's, and the plan says so rather than stretching a sitting past what a sitting is.
            var baseMinutes = weekBudget / kinds.Count;
            var remainder = weekBudget % kinds.Count;
            for (var i = 0; i < kinds.Count; i++)
            {
                var step = kinds[i];
                if (step is null)
                {
                    continue;
                }

                var minutes = Math.Clamp(
                    baseMinutes + (i < remainder ? 1 : 0),
                    MinimumStepMinutes,
                    MaximumStepMinutes);

                planned.Add(step with { WeekSequence = i + 1, EstimatedMinutes = minutes });
            }
        }

        return planned;
    }

    /// <summary>
    /// D10's pedagogical order for one week. Non-null entries only, so a week whose skills supply less
    /// than <paramref name="drillCount"/> drills is honestly shorter rather than padded with repeats.
    /// </summary>
    private static List<PlannedPathStep?> BuildWeekKinds(
        IReadOnlyList<SkillPlanBlock> blocks, int week, int drillCount, bool wantsLesson, bool wantsMock)
    {
        var ordered = new List<PlannedPathStep?>(drillCount + 2);

        // Consecutive steps alternate skills: index i walks the block list round-robin, so two steps on
        // one skill never sit next to each other while another skill has capacity.
        for (var i = 0; i < drillCount; i++)
        {
            var block = blocks[i % blocks.Count];
            if (block.TopicIds.Count == 0)
            {
                continue;
            }

            // Blocked practice before interleaved review: the first pass through a topic is a focus
            // drill, and only a later week reviews it spaced.
            var type = week == 1
                ? PathStepType.FocusPractice
                : i % 2 == 0 ? PathStepType.FocusPractice : PathStepType.ReviewSpaced;

            // #219: week one starts on the topic the placement saw go badly, when it saw one this block
            // can drill. The hint only permutes topics the block already holds at this level (the block
            // was built from drillable stock), so a placement cannot make week one drill an empty cell.
            // Every other week keeps the block's own order: a hint is about where to START.
            var topicId = week == 1
                ? FirstWeekTopicOrder(block)[0]
                : block.TopicIds[(week - 1) % block.TopicIds.Count];

            var tier = SizingTierFor(block.Mastery);
            ordered.Add(new PlannedPathStep(
                week,
                WeekSequence: 0,
                type,
                block.SkillId,
                topicId,
                block.TargetCefr,
                tier,
                PlannedItemCount: ItemCountFor(tier, availableInCell: null),
                EstimatedMinutes: 0));
        }

        if (wantsLesson && blocks.FirstOrDefault(b => b.LessonId is not null) is { } lesson)
        {
            // A lesson is declarative knowledge before practice, so it sorts first among the week's
            // steps even though the plan is assembled practice-first.
            var tier = SizingTierFor(lesson.Mastery);
            ordered.Insert(0, new PlannedPathStep(
                week,
                WeekSequence: 0,
                PathStepType.ConceptLesson,
                lesson.SkillId,
                // #240: the lesson's OWN topic, which is the cell the lesson exists at. Falling back to
                // the block's first drill topic would name a cell the lesson is not pitched at.
                lesson.LessonTopicId
                    ?? (lesson.TopicIds.Count > 0 ? lesson.TopicIds[0] : DefaultTopicId(lesson)),
                lesson.TargetCefr,
                tier,
                // A lesson is sized in minutes, not items: the count belongs to the drills after it.
                PlannedItemCount: null,
                EstimatedMinutes: 0));
        }

        if (wantsMock && blocks.FirstOrDefault(b => b.MockExamId is not null) is { } mock)
        {
            ordered.Add(new PlannedPathStep(
                week,
                WeekSequence: 0,
                PathStepType.MockSection,
                mock.SkillId,
                mock.TopicIds.Count > 0 ? mock.TopicIds[0] : DefaultTopicId(mock),
                mock.TargetCefr,
                SizingTier.Developing,
                PlannedItemCount: null,
                EstimatedMinutes: 0));
        }

        return ordered;
    }

    /// <summary>
    /// #219 / D5: the first week's topic order, with the topics the placement saw go badly moved to
    /// the front. <b>A hint reorders; it never adds, removes or resizes.</b>
    /// <para>
    /// The block's <see cref="SkillPlanBlock.TopicIds"/> was built from drillable stock at this block's
    /// level, so a topic the placement touched at a different level is not in it and cannot be pulled
    /// in. Everything the hint names that the block does not hold is dropped, which is what keeps the
    /// placement from making week one drill a cell with nothing to serve.
    /// </para>
    /// <para>
    /// The order inside each group is the block's own, so two runs on the same data plan the same
    /// month. An empty or self-contradicting hint list yields the block's order unchanged, not an
    /// empty week.
    /// </para>
    /// </summary>
    public static IReadOnlyList<int> FirstWeekTopicOrder(SkillPlanBlock block)
    {
        if (block.PlacementWeakTopicIds is not { Count: > 0 } hinted)
        {
            return block.TopicIds;
        }

        var weak = hinted.ToHashSet();
        // The block's own position is the tie-break, so two runs plan the same month.
        var position = block.TopicIds
            .Select((topicId, index) => (topicId, index))
            .ToDictionary(x => x.topicId, x => x.index);

        return block.TopicIds
            .OrderByDescending(weak.Contains)
            .ThenBy(t => position[t])
            .ToList();
    }

